int countRestrictedPaths(int n, std::vector<std::vector<int>>& edges, std::vector<int>& restricted) {
    std::unordered_set<int> restrictedSet(restricted.begin(), restricted.end());
    std::vector<std::vector<int>> graph(n);

    // Build the graph
    for (const auto& edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    // Priority queue to perform Dijkstra's algorithm
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> pq;
    pq.push({0, n - 1}); // Start from node n-1 with distance 0

    std::vector<int> dist(n, INT_MAX);
    dist[n - 1] = 0;

    while (!pq.empty()) {
        int currentDist = pq.top().first;
        int currentNode = pq.top().second;
        pq.pop();

        if (currentDist > dist[currentNode]) continue;

        for (int neighbor : graph[currentNode]) {
            if (restrictedSet.find(neighbor) != restrictedSet.end()) continue;

            int newDist = currentDist + 1;
            if (newDist < dist[neighbor]) {
                dist[neighbor] = newDist;
                pq.push({newDist, neighbor});
            }
        }
    }

    return dist[0];
}
