        return false; // Out of bounds, return false
    }

    if (grid[i][j] == 1) {
        return true; // Already visited land, return true
    }

    grid[i][j] = 1; // Mark as visited

    // Check all four directions
    bool up = dfs(grid, i - 1, j);
    bool down = dfs(grid, i + 1, j);
    bool left = dfs(grid, i, j - 1);
    bool right = dfs(grid, i, j + 1);

    // If any direction returns false, it means the island is not closed
    return up && down && left && right;
}

int closedIsland(std::vector<std::vector<int>>& grid) {
    int count = 0;

    // Iterate over the grid
    for (int i = 0; i < grid.size(); ++i) {
        for (int j = 0; j < grid[0].size(); ++j) {
            // If the cell is water (0) and the dfs call returns true, it's a closed island
            if (grid[i][j] == 0 && dfs(grid, i, j)) {
                count++;
            }
        }
    }

    return count;
}
