            for (int j = 0; j <= word.length(); j++) {
                String prefix = word.substring(0, j);
                String suffix = word.substring(j);

                // Check if the prefix is a palindrome and the suffix exists in the map
                if (isPalindrome(prefix) && wordIndexMap.containsKey(suffix)) {
