#include <vector>
#include <queue>
#include <stack>

std::vector<int> findOrder(int numCourses, std::vector<std::vector<int>>& prerequisites) {
    std::vector<std::vector<int>> adj(numCourses);
    std::vector<int> inDegree(numCourses, 0);
    std::stack<int> courseOrder;

    // Build the adjacency list and calculate in-degrees
    for (auto& p : prerequisites) {
        adj[p[1]].push_back(p[0]);
        inDegree[p[0]]++;
    }

    // Initialize the queue with courses with no prerequisites
    std::queue<int> q;
    for (int i = 0; i < numCourses; i++) {
        if (inDegree[i] == 0) q.push(i);
    }

    // Process courses
    while (!q.empty()) {
        int currCourse = q.front();
        q.pop();
        courseOrder.push(currCourse);
        numCourses--;

        // Decrease in-degree of adjacent courses
        for (int nextCourse : adj[currCourse]) {
            inDegree[nextCourse]--;
            if (inDegree[nextCourse] == 0) q.push(nextCourse);
        }
    }

    // If all courses are processed, return the order
    if (numCourses == 0) {
        std::vector<int> result;
        while (!courseOrder.empty()) {
            result.push_back(courseOrder.top());
            courseOrder.pop();
