        return result;
    }

    public int maxCost(int[] nums, int[] cost) {
        int n = nums.length;
        int[][] dp = new int[n][n];

        // Initialize the dp table
        for (int i = 0; i < n; i++) {
            dp[i][i] = cost[i];
        }

        // Fill the dp table
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j] + cost[i] * cost[j]);
                }
            }
        }

        return dp[0][n - 1];
    }
}
```

