bool hasHamiltonianPath(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> graph(n);
    for (const auto& edge : edges) {
        graph[edge[0]].push_back(edge[1]);
        graph[edge[1]].push_back(edge[0]);
    }

    std::vector<bool> visited(n, false);

    // Helper function to perform DFS
    bool dfs(int node, int pathLength) {
        if (pathLength == n) {
            return true; // Found a Hamiltonian path
        }
        visited[node] = true;
        for (int neighbor : graph[node]) {
            if (!visited[neighbor] && dfs(neighbor, pathLength + 1)) {
                return true;
            }
        }
        visited[node] = false;
        return false;
    }

    // Try starting DFS from each node
    for (int i = 0; i < n; ++i) {
        if (dfs(i, 1)) {
            return true;
        }
    }

    return false;
}

