import java.util.*;

class Solution {
    public boolean canReachWithMaxDistance(int[][] graph, int maxDistance) {
        int n = graph.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : graph) {
            adj[edge[0]].add(edge[1]);
            adj[edge[1]].add(edge[0]);
        }

        boolean[] visited = new boolean[n];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 0}); // Start from node 0 with distance 0

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int node = current[0];
            int distance = current[1];

            if (node == n - 1) {
                return true; // Reached the last node
            }

            if (visited[node]) {
                continue;
            }
            visited[node] = true;

            for (int neighbor : adj.get(node)) {
                if (distance + 1 <= maxDistance) {
                    queue.offer(new int[]{neighbor, distance + 1});
                }
            }
        }

        return false; // Did not reach the last node within the max distance
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int[][] graph = {{1, 2, 3}, {0, 2}, {0, 1, 3}, {0, 2}};
        int maxDistance = 2;
        System.out.println(solution.canReachWithMaxDistance(graph, maxDistance)); // Output: true
    }
}
```

