import java.util.*;

public class StringRearranger {

    public static String rearrangeString(String s, int k) {
        if (k <= 1 || s.length() % k != 0) {
            return s; // No rearrangement needed if k is 1 or not divisible by the length of the string
        }

        int n = s.length();
        int[] charCount = new int[26]; // To count occurrences of each character

        // Count the occurrences of each character
        for (char c : s.toCharArray()) {
            charCount[c - 'a']++;
        }

        PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> charCount[b - 'a'] - charCount[a - 'a']);
        maxHeap.addAll(Arrays.asList(s.toCharArray()));

        StringBuilder result = new StringBuilder();

        while (!maxHeap.isEmpty()) {
            List<Character> currentBatch = new ArrayList<>();
            int batchCount = Math.min(k, maxHeap.size());

            // Collect up to k characters with the highest frequency
            for (int i = 0; i < batchCount; i++) {
                char currentChar = maxHeap.poll();
                currentBatch.add(currentChar);
                charCount[currentChar - 'a']--;

                // If there are still characters left with the same frequency, add them back to the heap
                if (charCount[currentChar - 'a'] > 0) {
                    maxHeap.offer(currentChar);
                }
            }

            // If we couldn't form a complete batch, return the result so far
            if (currentBatch.size() < k) {
                return result.toString();
            }

            // Append the current batch to the result
            for (char c : currentBatch) {
                result.append(c);
            }
        }

        return result.toString();
    }

    public static void main(String[] args) {
        System.out.println(rearrangeString("aabbcc", 3)); // Output: "abcabc"
    }
}
