int countPartitions(std::vector<int>& nums, int goal) {
    int n = nums.size();
    int totalSum = 0;

    // Calculate the total sum of the array
    for (int num : nums) {
        totalSum += num;
    }

    // If the total sum is less than the goal or if the goal is negative, no valid partitions exist
    if (totalSum < goal || goal < 0) {
        return 0;
    }

    // If the goal is equal to the total sum, there is exactly one way to partition the array (all elements in one subarray)
    if (goal == totalSum) {
        return 1;
    }

    // If the goal is greater than half of the total sum, no valid partitions exist
    if (goal > totalSum / 2) {
        return 0;
    }

    // Initialize the DP table
    std::unordered_map<int, int> dp;
    dp[0] = 1; // There is one way to have a sum of 0: with an empty subarray

    // Iterate through each number in the array
    for (int num : nums) {
        // Create a new map to store the updated DP values
        std::unordered_map<int, int> newDp;

        // Update the DP table for each possible sum
        for (const auto& [sum, count] : dp) {
            int newSum = sum + num;
            if (newSum <= goal) {
                newDp[newSum] += count;
            }
        }

        // Merge the new DP table with the old one
        dp = newDp;
    }

    // The result is the number of ways to achieve the goal sum
