int numberOfWaysToDistributeTasks(const std::vector<std::vector<int>>& tasks, int maxTasksPerWorker) {
    int n = tasks.size();
    int totalTasks = 0;

    // Calculate the total number of tasks
    for (const auto& task : tasks) {
        totalTasks += task[0];
    }

