    }

    // Calculate the number of ways to distribute tasks
    long long result = 1;
    for (int i = 1; i <= maxTasksPerWorker; ++i) {
        result = (result * factorial(taskCount[i])) % (1e9 + 7);
    }

    // Divide by the factorial of the number of workers to account for overcounting
    result = result / factorial(n);

    return static_cast<int>(result);
}

// Helper function to calculate factorial
long long factorial(int num) {
    long long fact = 1;
    for (int i = 2; i <= num; ++i) {
