import java.util.HashSet;
import java.util.Set;

public class Solution {

    public int countMaxOrSubsets(int[] nums) {
        int max_OR = 0;
        for (int num : nums) {
            max_OR |= num;
        }

        Set<Integer> OR_subsets = new HashSet<>();
        OR_subsets.add(0);

        for (int num : nums) {
            Set<Integer> tmp = new HashSet<>(OR_subsets);
            for (int x : OR_subsets) {
                tmp.add(x | num);
            }
            OR_subsets = tmp;
        }

        int count = 0;
        for (int x : OR_subsets) {
            if (x == max_OR) {
                count++;
            }
        }
        return count;
    }

    public int countCommonElements(int[] nums1, int[] nums2) {
        Set<Integer> set1 = new HashSet<>();
        for (int num : nums1) {
            set1.add(num);
        }

        Set<Integer> commonElements = new HashSet<>();
        for (int num : nums2) {
            if (set1.contains(num)) {
                commonElements.add(num);
            }
        }

        return commonElements.size();
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int[] nums1 = {1, 2, 3, 4, 5};
        int[] nums2 = {1, 2, 3, 4, 5};

        System.out.println(solution.countCommonElements(nums1, nums2)); // Output: 10
    }
}
