public class Solution {
    public List<Integer> rotateRight(List<Integer> nums, int k) {
        if (nums == null || nums.isEmpty() || k == 0) return nums;

        int n = nums.size();
        k = k % n; // In case k is greater than the length of the list

        // Convert the list to a circular linked list
        ListNode head = new ListNode(nums.get(0));
        ListNode current = head;
        for (int i = 1; i < n; i++) {
            current.next = new ListNode(nums.get(i));
            current = current.next;
        }
        current.next = head; // Make it circular

