        for (int i = 0; i < n - k - 1; i++) {
            current = current.next;
        }

        // Extract the rotated list
        List<Integer> result = new ArrayList<>();
        while (current != null) {
            result.add(current.val);
            current = current.next;
            if (current == head) break; // Avoid adding the head again
        }

        return result;
    }

