def evaluateExpression(s: str) -> int:
    def helper(expr: str) -> int:
        if expr.isdigit():
            return int(expr)

        result = None
        for i in range(len(expr)):
            if expr[i] in "+-*":
                left = helper(expr[:i])
                right = helper(expr[i+1:])
                if expr[i] == '+':
                    result = left + right
                elif expr[i] == '-':
                    result = left - right
                elif expr[i] == '*':
                    result = left * right

        return result

    return helper(s)
