public class ExpressionEvaluator {

    public static List<Integer> evaluateExpression(String expression) {
        List<Integer> results = new ArrayList<>();
        if (expression == null || expression.isEmpty()) {
            return results;
        }

        // Split the expression into tokens
        String[] tokens = expression.split(" ");
        evaluate(tokens, 0, tokens.length - 1, results);
        return results;
    }

    private static void evaluate(String[] tokens, int start, int end, List<Integer> results) {
        if (start > end) {
            return;
        }

        if (start == end) {
            results.add(Integer.parseInt(tokens[start]));
            return;
        }

        for (int i = start; i <= end; i++) {
            if (!isOperator(tokens[i])) {
                continue;
            }

            evaluate(tokens, start, i - 1, results);
            evaluate(tokens, i + 1, end, results);

            char operator = tokens[i].charAt(0);
            int result = 0;

            switch (operator) {
                case '+':
                    result = results.get(0) + results.get(1);
                    break;
                case '-':
                    result = results.get(0) - results.get(1);
                    break;
                case '*':
                    result = results.get(0) * results.get(1);
                    break;
            }

            results.clear();
            results.add(result);
        }
    }

    private static boolean isOperator(String token) {
        return token.equals("+") || token.equals("-") || token.equals("*");
    }

    public static void main(String[] args) {
