            int index = indices[i];
            int value = nums[index];
            // Add the current value to the Fenwick Tree
            fenwickTree.update(index + 1, 1);
            // The result for the current index is the sum of the Fenwick Tree up to index
            result[index] = fenwickTree.query(index + 1);
        }

        return result;
    }

    // Fenwick Tree implementation
    private static class FenwickTree {
        private int[] tree;

        public FenwickTree(int n) {
            tree = new int[n + 1];
        }

        public void update(int index, int delta) {
            while (index <= tree.length - 1) {
                tree[index] += delta;
                index += lowbit(index);
            }
        }

        public int query(int index) {
            int sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= lowbit(index);
            }
            return sum;
        }

        private int lowbit(int x) {
            return x & (-x);
        }
    }
