class Solution {
    // Helper function to decode the string
    private String decodeHelper(String s, int start) {
        StringBuilder result = new StringBuilder();
        int count = 0;
        int ptr = start;

        while (ptr < s.length()) {
            if (Character.isDigit(s.charAt(ptr))) {
                int count = 0;
                while (Character.isDigit(s.charAt(ptr))) {
                    count = count * 10 + (s.charAt(ptr) - '0');
                    ptr++;
