                ptr++; // Skip the closing bracket
            } else if (s.charAt(ptr) == ']') {
                break;
            } else {
                result.append(s.charAt(ptr));
                ptr++;
            }
        }

        return result.toString();
    }

    // Main function to decode the string
    public String decodeString(String s) {
        return decodeHelper(s, 0);
    }
}
