public class LongestChain {

    public static List<List<Integer>> findLongestChains(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums == null || nums.length == 0) {
            return result;
        }

        // Sort the numbers in ascending order
        Arrays.sort(nums);

        // Initialize the list to store the longest chains
        List<List<Integer>> chains = new ArrayList<>();
        chains.add(new ArrayList<>());
        chains.get(0).add(nums[0]);

        for (int i = 1; i < nums.length; i++) {
            List<Integer> currentChain = new ArrayList<>();
            currentChain.add(nums[i]);

            // Find the longest chain that can be extended with the current number
            for (List<Integer> chain : chains) {
                if (chain.get(chain.size() - 1) < nums[i]) {
                    currentChain.addAll(chain);
                    break;
                }
            }

            // Add the current chain to the list of chains
            chains.add(currentChain);
        }

        // Remove all chains that are not the longest
        int maxLength = 0;
        for (List<Integer> chain : chains) {
            if (chain.size() > maxLength) {
                maxLength = chain.size();
            }
        }
        for (int i = 0; i < chains.size(); i++) {
            if (chains.get(i).size() != maxLength) {
                chains.remove(i--);
            }
        }

