public class Solution {
    public int countPairs(int[][] workers, int[][] bikes, int distanceThreshold) {
        int count = 0;
        int m = workers.length;
        int n = bikes.length;

        // Iterate over each worker
        for (int i = 0; i < m; i++) {
            int[] worker = workers[i];
            // Iterate over each bike
