    // Calculate the shortest distance from each cell to all houses
    int min_dist = INT_MAX;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 0) {
                int total_dist = 0;
                for (int k = 0; k < house_count; k++) {
                    total_dist += dist_sum[i][j];
                }
                min_dist = min(min_dist, total_dist);
            }
        }
    }

    return min_dist == INT_MAX ? -1 : min_dist;
}
```

